import sys,math; sys.path.insert(0,'/tmp/ft/tools')
from parse import parse
o,r=parse('/tmp/ft/w05/sgn.bin')
m,n,d=o['input']; ws=[w[0] for w in o['words']]
rows={ws[i]:list(d[i*n:(i+1)*n]) for i in range(len(ws))}
def dot(a,b): return sum(x*y for x,y in zip(a,b))
def norm(a): return math.sqrt(dot(a,a))
A,B,C='tree','cherry','pen'
q=[0.0]*n
for w,sgn in ((A,1.0),(B,-1.0),(C,1.0)):
    v=rows[w]; s=sgn/(norm(v)+1e-8)
    q=[q[i]+v[i]*s for i in range(n)]
qn=norm(q); ban={A,B,C}
sims=[]
for w in ws:
    if w in ban: continue
    v=rows[w]; nv=norm(v); u=[x/nv for x in v] if nv>0 else v
    sims.append((dot(u,q)/qn, w))
sims.sort(key=lambda t:-t[0])
print('normalize-each-then-combine:')
for s,w in sims[:10]: print(' %s %g'%(w,s))
print('observed:  apple 0.662304 fish 0.611028 river 0.468071 star 0.42871 table 0.380141 mountain 0.305569 car 0.242142 chair 0.183707 house 0.151181 bird 0.0591633')
"

